{
  "incident_detected": false,
  "root_cause_hypothesis": "The iOS driving-licence dip is consistent with sampling variation in a small weekly slice, not evidence of a broken iOS release. Approvals rebounded the following week, and the changepoint scan detected no sustained break.",
  "supporting_metrics": [
    {
      "name": "ios driving_licence weekly KYC approval rate",
      "baseline_value": 0.886076,
      "anomaly_value": 0.804598,
      "unit": "fraction",
      "sql": "SELECT date_trunc('week', decision_date)::DATE AS week, sum(n_decisions) AS n, sum(n_approved) AS k, sum(n_approved)::DOUBLE /sum(n_decisions) AS rate FROM agg_kyc_daily WHERE platform='ios' AND doc_type='driving_licence' GROUP BY 1 ORDER BY 1"
    },
    {
      "name": "ios driving_licence weekly KYC decisions",
      "baseline_value": 79,
      "anomaly_value": 87,
      "unit": "count",
      "sql": "SELECT date_trunc('week', decision_date)::DATE AS week, sum(n_decisions) AS n, sum(n_approved) AS k, sum(n_approved)::DOUBLE /sum(n_decisions) AS rate FROM agg_kyc_daily WHERE platform='ios' AND doc_type='driving_licence' GROUP BY 1 ORDER BY 1"
    },
    {
      "name": "ios driving_licence week-over-week approval two-proportion test p-value",
      "baseline_value": null,
      "anomaly_value": 0.149,
      "unit": "fraction",
      "sql": "calculate_uplift_or_stats(metric_slice={analysis:'two_proportion_test',platform:null,doc_type:null,channel:null,segment_by:null,k_a:70,n_a:79,k_b:70,n_b:87})"
    },
    {
      "name": "ios driving_licence baseline weekly approval rate standard deviation, 2026-01-05 to 2026-04-06",
      "baseline_value": 0.033685,
      "anomaly_value": null,
      "unit": "fraction",
      "sql": "WITH w AS (SELECT date_trunc('week',decision_date)::DATE AS week_start,sum(n_approved)::DOUBLE/sum(n_decisions) AS rate FROM agg_kyc_daily WHERE platform='ios' AND doc_type='driving_licence' GROUP BY 1) SELECT avg(rate) baseline_weekly_mean,stddev_samp(rate) baseline_weekly_sd,min(rate) baseline_weekly_min,max(rate) baseline_weekly_max FROM w WHERE week_start >= DATE '2026-01-05' AND week_start < DATE '2026-04-13'"
    },
    {
      "name": "ios driving_licence KYC changepoint maximum LLR versus detection threshold",
      "baseline_value": 25,
      "anomaly_value": 3.1,
      "unit": "LLR",
      "sql": "calculate_uplift_or_stats(metric_slice={analysis:'kyc_changepoint',platform:'ios',doc_type:'driving_licence',channel:null,segment_by:null,k_a:null,n_a:null,k_b:null,n_b:null})"
    },
    {
      "name": "ios driving_licence KYC approval rate, week of 2026-04-20",
      "baseline_value": 0.886076,
      "anomaly_value": 0.882353,
      "unit": "fraction",
      "sql": "SELECT date_trunc('week', decision_date)::DATE AS week, sum(n_decisions) AS n, sum(n_approved) AS k, sum(n_approved)::DOUBLE /sum(n_decisions) AS rate FROM agg_kyc_daily WHERE platform='ios' AND doc_type='driving_licence' GROUP BY 1 ORDER BY 1"
    }
  ],
  "recommended_action": "NO_ACTION_NOISE",
  "reasoning_summary": "Approvals were 70/87 in the week of 13 April versus 70/79 the preceding week; the difference is not statistically distinguishable from sampling noise (p=0.149). Historical weekly variability and the changepoint scan provide no evidence of a sustained incident: maximum LLR was 3.1 against a detection threshold of 25. The following week's approval rate recovered to 0.882353. Do not roll back iOS based on this dip; continue routine monitoring."
}
